%[text] # Motor Drive Unit - Simulation Case
%[text] ## Regenerative braking
%[text] Test that the motor can convert mechanical power to electric power.
mdl = "MotorDriveUnit_TestModel";
load_system(mdl)
MotorDriveUnit_TestModelSetup
%[text] Select model to use.
MotorDriveUnit_setRefsub_SystemTable %[output:5337e24e]
%[text] Load simulation case.
MotorDriveUnit_setSimCase_RegenBrake %[output:492bb0de]
%[text] Run simulation.
simOut = sim(mdl);
%[text] Visually inspect the result.
simData = extractTimetable(simOut.logsout);
sigNames = [
  "Motor torque command"
  "Axle torque input"
  "Motor power rate"
  "Motor speed"
  "Battery power"
  "Battery current"
  "Battery voltage"
  ];
for i = 1 : numel(sigNames) %[output:group:3a20ccb5]
  TimetableSingleSignalPlot( ... %[output:06c3646b] %[output:3bfa6c12] %[output:609d663c] %[output:4c169418] %[output:25eff019] %[output:9073655c] %[output:28bc0023]
    Timetable = simData, ... %[output:06c3646b] %[output:3bfa6c12] %[output:609d663c] %[output:4c169418] %[output:25eff019] %[output:9073655c] %[output:28bc0023]
    SignalName = sigNames(i), ... %[output:06c3646b] %[output:3bfa6c12] %[output:609d663c] %[output:4c169418] %[output:25eff019] %[output:9073655c] %[output:28bc0023]
    PlotHeight = 200 ); %[output:06c3646b] %[output:3bfa6c12] %[output:609d663c] %[output:4c169418] %[output:25eff019] %[output:9073655c] %[output:28bc0023]
end %[output:group:3a20ccb5]
